TEMAS = ["o maior mico da vida","o primeiro emprego","a viagem mais maluca","o pior presente que já ganhou","o que comeu ontem","o sonho da noite passada","o primeiro beijo","um medo bobo","uma superstição","um apelido de infância","o professor mais marcante","uma mania","o filme preferido","a música do momento","um segredo inofensivo","o dia mais feliz","o que faria com um milhão","uma festa inesquecível","a pior comida que já provou","um talento escondido","a última vez que chorou","o que queria ser quando crescesse","uma viagem que quer fazer","um erro engraçado no trabalho","um mico na escola","um vizinho maluco","uma briga boba","um conselho que recebeu","uma promessa de ano novo","o programa de domingo","a primeira casa que morou","o melhor churrasco","o primeiro celular","uma coincidência","uma sorte inesperada","uma dívida que ficou","uma bagunça que fez","a pior viagem de ônibus","um apelido que odeia","uma comida que odeia"]
FRASES = ["que absurdo","não acredito","eu avisei","já vi esse filme","por que não?","é isso aí","tô fora","pode crer","que horas são?","me conta mais","deixa pra lá","ninguém merece","quem diria","isso é verdade?","qual é a graça?","tá brincando","desculpa o atraso","parabéns pra você","feliz ano novo","bom dia, flor do dia","como é que é?","faz sentido","eu já sabia","nem tudo é o que parece","depois eu explico","pode repetir?","me poupe","fala sério","cuidado com o degrau","tá quente aqui"]
OBJ = ["uma série","um filme","um restaurante","um podcast","um livro","uma música","um lugar para viajar","um jogo","um canal de vídeo","um aplicativo","uma sobremesa","um passeio","uma receita","um presente barato","um bar"]
def build():
    out=[]
    forms = ["Faça alguém dizer “{w}” sem você falar antes","Faça alguém soltar a palavra “{w}” na conversa","Leve a conversa até alguém dizer “{w}”"]
    for i,w in enumerate(WORDS): out.append(forms[i % 3].format(w=w)+"|"+("2" if len(w) > 9 else "1"))
    for g in GESTOS: out.append(f"Faça alguém {g} sem você pedir|{2 if len(g)>22 else 1}")
    for t in TEMAS: out.append(f"Consiga que alguém fale sobre {t}|2")
    for f in FRASES: out.append(f"Faça alguém falar a frase “{f}”|3")
    for o in OBJ: out.append(f"Consiga que alguém recomende {o}|1")
    for o in OBJ: out.append(f"Faça alguém pedir sua opinião sobre {o}|2")
    return out
if __name__=='__main__': print(len(build()))
